insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz não permitirá que a testemunha manifeste suas apreciações pessoais, salvo quando inseparáveis da narrativa do fato.', '["Testemunha não manifesta apreciações pessoais.","Exceção: se inseparáveis da narrativa do fato."]'::jsonb, '["Testemunha relata fatos, não opiniões."]'::jsonb, 'O juiz impede a testemunha de opinar sobre a culpa do acusado.', '["Assertiva que permite sempre à testemunha emitir opiniões erra."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-213'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes de iniciado o depoimento, as partes poderão contraditar a testemunha ou arguir circunstâncias ou defeitos que a tornem suspeita de parcialidade ou indigna de fé. O juiz fará consignar a contradita ou arguição e a resposta da testemunha, mas só excluirá a testemunha ou não lhe deferirá compromisso nos casos previstos nos arts. 207 e 208.', '["Contradita antes do depoimento.","Juiz registra a contradita e a resposta.","Exclusão da testemunha só nos casos dos arts. 207 e 208."]'::jsonb, '["Contradita registrada não exclui a testemunha, salvo hipóteses legais."]'::jsonb, 'A defesa contradita a testemunha que é inimiga do acusado; o juiz registra e, em regra, mantém o depoimento.', '["Assertiva que obriga o juiz a excluir toda testemunha contraditada erra."]'::jsonb, '[{"termo":"Contradita","significado":"Impugnação da testemunha antes de depor."}]'::jsonb, '["Art. 207","Art. 208"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-214'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na redação do depoimento, o juiz deverá cingir-se, tanto quanto possível, às expressões usadas pelas testemunhas, reproduzindo fielmente as suas frases.', '["Registro fiel das expressões usadas pelas testemunhas."]'::jsonb, '["Fidelidade ao depoimento."]'::jsonb, 'O termo reproduz as frases da testemunha, e não uma versão resumida do juiz.', '["Assertiva que autoriza o juiz a parafrasear livremente o depoimento erra."]'::jsonb, '[]'::jsonb, '["Art. 216"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-215'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O depoimento da testemunha será reduzido a termo, assinado por ela, pelo juiz e pelas partes. Se a testemunha não souber assinar, ou não puder fazê-lo, pedirá a alguém que o faça por ela, depois de lido na presença de ambos.', '["Depoimento reduzido a termo.","Assinado pela testemunha, juiz e partes.","Se não souber ou não puder assinar, outra pessoa assina por ela, após a leitura."]'::jsonb, '["Hoje, o registro pode ser audiovisual (art. 405)."]'::jsonb, 'Testemunha analfabeta pede a alguém que assine por ela, depois da leitura.', '["Assertiva que dispensa a assinatura do juiz no termo do depoimento erra."]'::jsonb, '[]'::jsonb, '["Art. 215","Art. 405"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-216'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o juiz verificar que a presença do réu poderá causar humilhação, temor ou sério constrangimento à testemunha ou ao ofendido, de modo que prejudique a verdade do depoimento, fará a inquirição por videoconferência e, somente na impossibilidade dessa forma, determinará a retirada do réu, prosseguindo na inquirição com a presença do defensor. A adoção de qualquer dessas medidas deverá constar do termo, com os motivos.', '["Presença do réu que cause constrangimento à testemunha ou ao ofendido, a ponto de prejudicar a verdade do depoimento.","Preferência: videoconferência.","Só se impossível: retirada do réu, com o defensor presente.","Medida e motivos constam do termo."]'::jsonb, '["Ordem: primeiro videoconferência; depois, retirada do réu.","O defensor permanece."]'::jsonb, 'Vítima de ameaça tem medo do réu; o juiz a ouve por videoconferência.', '["Assertiva que determina a retirada do réu como primeira providência, antes da videoconferência, erra."]'::jsonb, '[]'::jsonb, '["Art. 210"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-217'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se, regularmente intimada, a testemunha deixar de comparecer sem motivo justificado, o juiz poderá requisitar à autoridade policial a sua apresentação ou determinar seja conduzida por oficial de justiça, que poderá solicitar o auxílio da força pública.', '["Testemunha regularmente intimada que falta sem motivo justificado.","Juiz requisita à polícia sua apresentação ou determina a condução por oficial de justiça.","Oficial pode pedir auxílio da força pública."]'::jsonb, '["Condução coercitiva da TESTEMUNHA faltosa (permitida).","Para o investigado, a condução coercitiva para interrogatório é vedada pelo STF (ADPF 444)."]'::jsonb, 'A testemunha, regularmente intimada, não comparece e é conduzida pelo oficial de justiça.', '["Assertiva que veda a condução coercitiva da testemunha faltosa erra."]'::jsonb, '[]'::jsonb, '["Art. 219"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-218'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá aplicar à testemunha faltosa a multa prevista no art. 453, sem prejuízo do processo penal por crime de desobediência, e condená-la ao pagamento das custas da diligência.', '["Multa à testemunha faltosa.","Sem prejuízo do processo por desobediência.","Pagamento das custas da diligência."]'::jsonb, '["As sanções se acumulam."]'::jsonb, 'A testemunha faltosa paga multa e as custas da condução.', '["Assertiva que impede a multa se houver processo por desobediência erra."]'::jsonb, '[]'::jsonb, '["Art. 218"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-219'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As pessoas impossibilitadas, por enfermidade ou por velhice, de comparecer para depor, serão inquiridas onde estiverem.', '["Testemunhas impossibilitadas por doença ou velhice são ouvidas no local onde estiverem."]'::jsonb, '["Inquirição no local em que se encontram."]'::jsonb, 'Idoso acamado é ouvido em sua residência.', '["Assertiva que obriga a testemunha enferma a comparecer à sede do juízo erra."]'::jsonb, '[]'::jsonb, '["Art. 221"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-220'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Algumas autoridades têm a prerrogativa de serem inquiridas em local, dia e hora previamente ajustados com o juiz: o Presidente e o Vice-Presidente da República, senadores e deputados federais, ministros de Estado, governadores, secretários de Estado, prefeitos, deputados estaduais, membros do Poder Judiciário, ministros e juízes dos Tribunais de Contas, entre outros. O Presidente e o Vice-Presidente da República e os presidentes do Senado Federal, da Câmara dos Deputados e do Supremo Tribunal Federal podem optar por depoimento por escrito, com perguntas formuladas pelas partes e deferidas pelo juiz, transmitidas por ofício. Os militares são requisitados à autoridade superior. Aos funcionários públicos aplica-se o art. 218, comunicando-se imediatamente ao chefe da repartição a expedição do mandado, com indicação do dia e da hora.', '["Altas autoridades têm prerrogativa de combinar dia, hora e local do depoimento.","Presidente, Vice-Presidente e presidentes do Senado, da Câmara e do STF podem depor por escrito.","Militares são requisitados à autoridade superior.","Funcionários públicos: condução do art. 218, com comunicação ao chefe da repartição."]'::jsonb, '["A prerrogativa é de ajustar data e local, e não de dispensa do depoimento."]'::jsonb, 'O governador é ouvido como testemunha em dia e hora previamente ajustados com o juiz.', '["Assertiva que dispensa as altas autoridades do dever de depor erra: elas têm a prerrogativa de ajustar dia, hora e local."]'::jsonb, '[]'::jsonb, '["Art. 218"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-221'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A testemunha que morar fora da jurisdição do juiz será inquirida pelo juiz do lugar de sua residência, expedindo-se carta precatória com prazo razoável, intimadas as partes. A expedição da precatória não suspende a instrução criminal. Findo o prazo marcado, poderá realizar-se o julgamento, mas a precatória, uma vez devolvida, será junta aos autos a todo tempo. A oitiva poderá ser feita por videoconferência ou outro recurso tecnológico de transmissão de sons e imagens em tempo real, permitida a presença do defensor, inclusive durante a audiência de instrução e julgamento.', '["Testemunha de outra jurisdição: ouvida pelo juiz do lugar de sua residência (precatória).","Partes são intimadas da expedição.","A precatória não suspende a instrução.","Findo o prazo, o julgamento pode ocorrer; a precatória é juntada quando devolvida.","Videoconferência admitida, com possibilidade de o defensor estar presente."]'::jsonb, '["Precatória NÃO suspende a instrução."]'::jsonb, 'Testemunha em outra comarca é ouvida por videoconferência durante a audiência.', '["Assertiva que suspende a instrução criminal até a devolução da precatória erra."]'::jsonb, '[{"termo":"Carta precatória","significado":"Pedido de um juízo a outro para praticar ato em sua jurisdição."}]'::jsonb, '["Art. 222-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-222'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As cartas rogatórias só serão expedidas se demonstrada previamente a sua imprescindibilidade, arcando a parte requerente com os custos de envio. Aplica-se às cartas rogatórias o disposto nos §§ 1º e 2º do art. 222.', '["Carta rogatória só se demonstrada previamente a imprescindibilidade.","Custos de envio pela parte requerente.","Aplicam-se os §§ 1º e 2º do art. 222 (não suspende a instrução; julgamento após o prazo)."]'::jsonb, '["Carta rogatória é dirigida à autoridade estrangeira."]'::jsonb, 'Para ouvir testemunha no exterior, a parte demonstra a imprescindibilidade e paga o envio.', '["Assertiva que dispensa a demonstração prévia da imprescindibilidade da carta rogatória erra."]'::jsonb, '[{"termo":"Carta rogatória","significado":"Pedido de cooperação a autoridade estrangeira."}]'::jsonb, '["Art. 222"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-222-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a testemunha não conhecer a língua nacional, será nomeado intérprete para traduzir as perguntas e respostas. Tratando-se de mudo, surdo ou surdo-mudo, procede-se conforme o art. 192.', '["Testemunha que não fala o idioma nacional: intérprete.","Mudo, surdo ou surdo-mudo: forma do art. 192."]'::jsonb, '["Mesma sistemática do interrogatório."]'::jsonb, 'Testemunha estrangeira depõe com a ajuda de intérprete nomeado.', '["Assertiva que dispensa intérprete para testemunha que não conhece a língua nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 192","Art. 193"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-223'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As testemunhas comunicarão ao juiz, dentro de um ano, qualquer mudança de residência, sujeitando-se, pela simples omissão, às penas do não comparecimento.', '["Testemunha comunica ao juiz, em um ano, mudança de residência.","A omissão sujeita às penas do não comparecimento."]'::jsonb, '["Prazo de um ano."]'::jsonb, 'Testemunha muda de endereço e deixa de avisar o juízo: sujeita-se às penas da falta.', '["Assertiva que dispensa a comunicação de mudança de residência pela testemunha erra."]'::jsonb, '[]'::jsonb, '["Art. 219"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-224'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se qualquer testemunha houver de ausentar-se, ou, por enfermidade ou por velhice, inspirar receio de que ao tempo da instrução criminal já não exista, o juiz poderá, de ofício ou a requerimento de qualquer das partes, tomar-lhe antecipadamente o depoimento.', '["Testemunha que vai se ausentar ou corre risco de não existir ao tempo da instrução.","Juiz colhe o depoimento antecipadamente, de ofício ou a requerimento."]'::jsonb, '["Produção antecipada de prova testemunhal."]'::jsonb, 'Testemunha idosa e muito doente é ouvida antecipadamente.', '["Assertiva que exige requerimento das partes para a oitiva antecipada erra: pode ser de ofício."]'::jsonb, '[]'::jsonb, '["Art. 156"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-225'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando houver necessidade de fazer-se o reconhecimento de pessoa, procede-se assim: a pessoa que tiver de fazer o reconhecimento é convidada a descrever a pessoa a ser reconhecida; esta será colocada, se possível, ao lado de outras que tiverem qualquer semelhança, convidando-se quem faz o reconhecimento a apontá-la; se houver razão para recear que a pessoa chamada não diga a verdade em face da que deve ser reconhecida, por intimidação ou outra influência, a autoridade providenciará para que esta não veja aquela; do ato lavra-se auto pormenorizado, subscrito pela autoridade, pela pessoa que reconheceu e por duas testemunhas presenciais. O inciso III não se aplica na instrução criminal ou em plenário.', '["I: descrição prévia da pessoa a ser reconhecida.","II: colocação ao lado de pessoas semelhantes, se possível.","III: se houver receio de intimidação, a pessoa a reconhecer não vê a reconhecenda.","IV: auto pormenorizado, subscrito pela autoridade, pelo reconhecedor e por duas testemunhas.","Parágrafo único: o inciso III não se aplica na instrução ou no plenário."]'::jsonb, '["O STJ tem exigido a observância do procedimento do art. 226 sob pena de invalidade do reconhecimento.","O parágrafo único afasta o inciso III na instrução e no plenário."]'::jsonb, 'A vítima descreve o autor e depois o aponta entre pessoas parecidas.', '["Assertiva que dispensa a descrição prévia pela pessoa que fará o reconhecimento erra."]'::jsonb, '[]'::jsonb, '["Art. 227","Art. 228"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-226'
