insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A acareação será admitida entre acusados, entre acusado e testemunha, entre testemunhas, entre acusado ou testemunha e a pessoa ofendida, e entre as pessoas ofendidas, sempre que divergirem, em suas declarações, sobre fatos ou circunstâncias relevantes. Os acareados serão reperguntados, para que expliquem os pontos de divergência, reduzindo-se a termo o ato.', '["Cabe entre acusados, testemunhas, ofendidos e entre esses grupos.","Pressuposto: divergência sobre fatos ou circunstâncias relevantes.","Acareados são reperguntados.","O ato é reduzido a termo."]'::jsonb, '["Exige divergência RELEVANTE."]'::jsonb, 'Duas testemunhas dão versões divergentes sobre ponto essencial e são acareadas.', '["Assertiva que admite acareação mesmo sem divergência erra."]'::jsonb, '[{"termo":"Acareação","significado":"Confronto entre pessoas que deram declarações divergentes."}]'::jsonb, '["Art. 230"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-229'
