insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se ausente alguma testemunha cujas declarações divirjam das de outra que esteja presente, a esta se darão a conhecer os pontos da divergência, consignando-se no auto o que explicar ou observar. Se subsistir a discordância, expedir-se-á precatória à autoridade do lugar onde resida a testemunha ausente, transcrevendo-se as declarações desta e as da testemunha presente, nos pontos em que divergirem, bem como o texto do referido auto, para que essa autoridade possa ouvir a testemunha ausente.', '["Testemunha ausente divergente da presente: dá-se conhecimento à presente dos pontos divergentes.","Subsistindo a discordância: precatória ao lugar de residência da ausente.","Transcrevem-se as declarações divergentes."]'::jsonb, '["Acareação por precatória."]'::jsonb, 'Testemunha em outra comarca é ouvida por precatória sobre a divergência.', '["Assertiva que dispensa a transcrição das declarações divergentes na precatória erra."]'::jsonb, '[]'::jsonb, '["Art. 229"]'::jsonb, 'under_review', 'claude'
