insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade ou seus agentes poderão penetrar no território de jurisdição alheia, ainda que de outro Estado, quando, para o fim de apreensão, forem no seguimento de pessoa ou coisa, devendo apresentar-se à competente autoridade local antes da diligência ou após, conforme a urgência. Entende-se que vão em seguimento quando, tendo conhecimento direto da remoção ou transporte, a seguirem sem interrupção, embora a percam de vista; ou, mesmo sem avistá-la, sabendo por informações fidedignas ou circunstâncias indiciárias que está sendo removida em determinada direção, forem ao seu encalço. As autoridades locais, havendo fundadas razões para duvidar da legitimidade das pessoas ou da legalidade dos mandados, poderão exigir as provas, mas sem frustrar a diligência.', '["Seguimento de pessoa ou coisa em outra jurisdição, mesmo de outro Estado.","Apresentação à autoridade local antes ou depois, conforme a urgência.","Seguimento: conhecimento direto e perseguição sem interrupção; ou informações fidedignas.","Autoridade local pode exigir provas de legitimidade, sem frustrar a diligência."]'::jsonb, '["Apresentação à autoridade local, antes ou depois, conforme a urgência."]'::jsonb, 'Policiais perseguem veículo com produto do crime para outro Estado e depois se apresentam à autoridade local.', '["Assertiva que exige sempre a apresentação prévia à autoridade local erra: pode ser depois, conforme a urgência."]'::jsonb, '[]'::jsonb, '["Art. 240"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-250'
