insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o acusado não atender à intimação para o interrogatório, reconhecimento ou qualquer outro ato que, sem ele, não possa ser realizado, a autoridade poderá mandar conduzi-lo à sua presença. O mandado conterá, além da ordem de condução, os requisitos do art. 352, no que lhe for aplicável. O texto remete a ADPFs sobre condução coercitiva.', '["Acusado que não atende à intimação pode ser conduzido, para atos que dependam dele.","Mandado contém os requisitos do art. 352."]'::jsonb, '["O STF (ADPF 395 e 444) considerou a condução coercitiva para interrogatório incompatível com a Constituição.","Continua possível para reconhecimento e atos que dependam da presença física do acusado."]'::jsonb, 'Para o reconhecimento de pessoa, pode ser determinada a condução do acusado que não comparece.', '["Assertiva que autoriza a condução coercitiva do acusado para interrogatório, nos termos do art. 260, erra, à luz das ADPFs 395 e 444."]'::jsonb, '[]'::jsonb, '["Art. 218","Art. 352"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-260'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum acusado, ainda que ausente ou foragido, será processado ou julgado sem defensor. A defesa técnica, quando realizada por defensor público ou dativo, será sempre exercida através de manifestação fundamentada.', '["Nenhum acusado é processado ou julgado sem defensor, ainda que ausente ou foragido.","Defensor público ou dativo: manifestação sempre fundamentada."]'::jsonb, '["A defesa técnica é indispensável.","Defesa meramente formal é nula."]'::jsonb, 'Réu foragido tem defensor nomeado para acompanhar o processo.', '["Assertiva que permite processar o réu foragido sem defensor erra."]'::jsonb, '[]'::jsonb, '["Art. 263"]'::jsonb, 'under_review', 'claude'
