insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O defensor não poderá abandonar o processo sem justo motivo, previamente comunicado ao juiz, sob pena de responder por infração disciplinar perante o órgão correicional competente. A audiência poderá ser adiada se, por motivo justificado, o defensor não puder comparecer. Incumbe ao defensor provar o impedimento até a abertura da audiência; não o fazendo, o juiz não determinará o adiamento de ato algum do processo, devendo nomear defensor substituto, ainda que provisoriamente ou só para o efeito do ato. Em caso de abandono, o acusado será intimado para constituir novo defensor, se quiser, e, se não for localizado, será nomeado defensor público ou advogado dativo.', '["Defensor não abandona o processo sem justo motivo previamente comunicado.","Abandono: infração disciplinar.","Adiamento da audiência por impedimento justificado.","Impedimento deve ser provado até a abertura da audiência.","Não provado: defensor substituto nomeado.","Abandono: intimação do acusado para constituir novo defensor; se não localizado, defensor público ou dativo."]'::jsonb, '["Prova do impedimento até a abertura da audiência."]'::jsonb, 'Defensor com impedimento prova a razão até a abertura da audiência e obtém o adiamento.', '["Assertiva que adia sempre a audiência pela ausência do defensor, sem prova do impedimento, erra."]'::jsonb, '[]'::jsonb, '["Art. 261"]'::jsonb, 'under_review', 'claude'
