select u.id, u.content_sha256, 'Em todos os termos da ação pública, poderá intervir, como assistente do Ministério Público, o ofendido ou seu representante legal ou, na falta, qualquer das pessoas mencionadas no art. 31.', '["Assistente de acusação na ação pública: ofendido ou representante legal.","Na falta: cônjuge, ascendente, descendente ou irmão (art. 31)."]'::jsonb, '["O assistente atua APENAS na ação penal pública."]'::jsonb, 'A vítima se habilita como assistente do MP no processo.', '["Assertiva que admite assistente de acusação na ação penal privada erra."]'::jsonb, '[{"termo":"Assistente de acusação","significado":"Quem auxilia o MP na ação penal pública."}]'::jsonb, '["Art. 31","Art. 269"]'::jsonb, 'under_review', 'claude'
