select u.id, u.content_sha256, 'O assistente será admitido enquanto não passar em julgado a sentença e receberá a causa no estado em que se achar.', '["Admissão enquanto não houver trânsito em julgado.","Recebe a causa no estado em que se encontra."]'::jsonb, '["Ingresso até o trânsito em julgado, sem retroceder o processo."]'::jsonb, 'A vítima se habilita como assistente após a instrução, recebendo o processo como está.', '["Assertiva que permite a habilitação do assistente após o trânsito em julgado erra."]'::jsonb, '[]'::jsonb, '["Art. 268"]'::jsonb, 'under_review', 'claude'
