insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao assistente será permitido propor meios de prova, requerer perguntas às testemunhas, aditar o libelo e os articulados, participar do debate oral e arrazoar os recursos interpostos pelo Ministério Público, ou por ele próprio, nos casos dos arts. 584, §1º, e 598. O juiz, ouvido o Ministério Público, decidirá acerca da realização das provas propostas pelo assistente. O processo prosseguirá independentemente de nova intimação do assistente, quando este, intimado, deixar de comparecer a qualquer dos atos da instrução ou do julgamento sem motivo de força maior devidamente comprovado.', '["Propor provas, requerer perguntas às testemunhas, aditar, participar do debate oral e arrazoar recursos.","Provas propostas: o juiz decide, ouvido o MP.","Falta injustificada do assistente: o processo prossegue sem nova intimação."]'::jsonb, '["Ausência do assistente sem força maior não paralisa o processo."]'::jsonb, 'O assistente propõe uma prova, e o juiz decide após ouvir o MP.', '["Assertiva que determina nova intimação do assistente faltoso sem motivo de força maior erra."]'::jsonb, '[]'::jsonb, '["Art. 268"]'::jsonb, 'under_review', 'claude'
