insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As prescrições sobre suspeição dos juízes estendem-se aos serventuários e funcionários da justiça, no que lhes for aplicável.', '["Regras de suspeição dos juízes valem para serventuários e funcionários da justiça."]'::jsonb, '["Extensão das regras de suspeição."]'::jsonb, 'Escrivão inimigo capital do acusado pode ser recusado.', '["Assertiva que exclui os serventuários das regras de suspeição erra."]'::jsonb, '[]'::jsonb, '["Art. 254","Art. 105"]'::jsonb, 'under_review', 'claude'
