insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O perito nomeado pela autoridade será obrigado a aceitar o encargo, sob pena de multa de cem a quinhentos mil-réis, salvo escusa atendível. Incorrerá na mesma multa o perito que, sem justa causa, provada imediatamente, deixar de acudir à intimação ou ao chamado da autoridade; não comparecer no dia e local designados para o exame; ou não der o laudo, ou concorrer para que a perícia não seja feita, nos prazos estabelecidos.', '["Perito nomeado é obrigado a aceitar, salvo escusa atendível.","Multa também por: não atender à intimação, faltar ao exame, não entregar o laudo no prazo."]'::jsonb, '["Valores de multa em moeda antiga."]'::jsonb, 'O perito não entrega o laudo no prazo, sem justa causa, e sofre multa.', '["Assertiva que permite ao perito recusar livremente o encargo erra: só com escusa atendível."]'::jsonb, '[]'::jsonb, '["Art. 278"]'::jsonb, 'under_review', 'claude'
