select u.id, u.content_sha256, 'Não será permitido o emprego de força, salvo a indispensável no caso de resistência ou de tentativa de fuga do preso.', '["Proibido o emprego de força.","Exceção: a indispensável, em caso de resistência ou tentativa de fuga."]'::jsonb, '["Súmula Vinculante 11: algemas só em caso de resistência, fundado receio de fuga ou perigo, com justificativa por escrito."]'::jsonb, 'A força é usada apenas na medida indispensável para vencer a resistência do preso.', '["Assertiva que permite o emprego de força sem necessidade na prisão erra."]'::jsonb, '[]'::jsonb, '["Art. 292"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-284'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade que ordenar a prisão fará expedir o respectivo mandado. O mandado de prisão será lavrado pelo escrivão e assinado pela autoridade; designará a pessoa a ser presa por seu nome, alcunha ou sinais característicos; mencionará a infração penal que motivar a prisão; declarará o valor da fiança arbitrada, quando afiançável a infração; e será dirigido a quem tiver qualidade para dar-lhe execução.', '["Mandado lavrado pelo escrivão e assinado pela autoridade.","Designa a pessoa por nome, alcunha ou sinais.","Menciona a infração.","Declara o valor da fiança, se afiançável.","Dirigido a quem pode executá-lo."]'::jsonb, '["Requisitos formais do mandado."]'::jsonb, 'O mandado traz o nome do preso, a infração e o valor da fiança arbitrada.', '["Assertiva que dispensa a menção da infração no mandado de prisão erra."]'::jsonb, '[]'::jsonb, '["Art. 286"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-285'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O mandado será passado em duplicata, e o executor entregará ao preso, logo depois da prisão, um dos exemplares com declaração do dia, hora e lugar da diligência. Da entrega deverá o preso passar recibo no outro exemplar; se recusar, não souber ou não puder escrever, o fato será mencionado em declaração assinada por duas testemunhas.', '["Mandado em duplicata.","Entrega de um exemplar ao preso, com dia, hora e lugar.","Recibo no outro exemplar.","Recusa ou impossibilidade: declaração assinada por duas testemunhas."]'::jsonb, '["Duas testemunhas na recusa."]'::jsonb, 'O preso recebe uma via do mandado e assina recibo na outra.', '["Assertiva que dispensa a entrega de exemplar do mandado ao preso erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-286'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a infração for inafiançável, a falta de exibição do mandado não obstará a prisão, e o preso, em tal caso, será imediatamente apresentado ao juiz que tiver expedido o mandado, para a realização de audiência de custódia.', '["Infração inafiançável: a falta de exibição do mandado não impede a prisão.","O preso é imediatamente apresentado ao juiz que expediu o mandado.","Realiza-se audiência de custódia."]'::jsonb, '["Só vale para infração INAFIANÇÁVEL."]'::jsonb, 'Em crime inafiançável, a prisão ocorre mesmo sem exibir o mandado no ato, com posterior apresentação ao juiz.', '["Assertiva que dispensa a audiência de custódia no caso do art. 287 erra."]'::jsonb, '[{"termo":"Audiência de custódia","significado":"Apresentação do preso ao juiz para controle da legalidade da prisão."}]'::jsonb, '["Art. 310"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-287'
