insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ninguém será recolhido à prisão sem que seja exibido o mandado ao respectivo diretor ou carcereiro, a quem será entregue cópia assinada pelo executor ou apresentada a guia expedida pela autoridade competente, devendo ser passado recibo da entrega do preso, com declaração de dia e hora. O recibo poderá ser passado no próprio exemplar do mandado, se este for o documento exibido.', '["Recolhimento à prisão exige exibição do mandado ao diretor ou carcereiro.","Cópia assinada pelo executor ou guia expedida pela autoridade.","Recibo com dia e hora."]'::jsonb, '["Formalidades de recolhimento."]'::jsonb, 'O diretor da unidade recebe o mandado e passa recibo da entrega do preso.', '["Assertiva que dispensa recibo da entrega do preso ao diretor erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
